const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{chromium}=require('playwright'),{parse}=require('../audits/audit-i18n-global.cjs');
const root=process.env.REFUS_ACTIONS_ASSET_DIR||path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8'),fixtures=JSON.parse(fs.readFileSync(path.join(__dirname,'fixtures/refus-actions-cas-20261113.json'),'utf8')),rows=JSON.parse(fs.readFileSync(path.join(__dirname,'../audits/I18N-REFUS-ACTIONS-871-sources.json'),'utf8'));
