test('refus : 1728 bascules sur 32 chemins, sans puis avec protocole #924, neuf langues, 320/390/1280, variables exactes et aucune action/PA/RPC supplémentaire',async()=>{
 const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});
 try{for(const compat of [false,true])for(const width of [320,390,1280]){const page=await browser.newPage({viewport:{width,height:800}}),errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.route('**/*',r=>r.abort());await page.setContent('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body class="plateau-body"><input id="draft" value="Brouillon conservé"><div id="rich" contenteditable="true"><b>Texte conservé</b></div><div id="result-toast"><div id="toast-result" class="toast-result"></div><div id="toast-sub" class="toast-sub"></div></div></body></html>');await page.addStyleTag({content:read('style.css')});await page.addScriptTag({content:read('i18n/i18next.min.js')});
 await page.evaluate(()=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.calls=[];window.incidents=[];window.noterIncidentSession=(...a)=>incidents.push(a);window.COUNTRIES={republic:{cur:'FR'},soviet:{cur:'PSK'}};window.state={char:{name:'Fixture',country:'republic'},pa:3,arg:700,inventory:[{id:'fixture'}],progression:{stage:2},currentBuilding:'fixture',currentRoom:'fixture'};for(const name of ['fetch','sbRpc','deduireCoutOrdre','doOrder'])window[name]=(...a)=>{calls.push([name,...a]);throw Error('Appel métier interdit');};window.snapshot=()=>JSON.stringify({state,calls,incidents,timer:window._toastTimer,draft:document.getElementById('draft').value,rich:document.getElementById('rich').innerHTML,focus:document.activeElement.id,start:document.getElementById('draft').selectionStart,end:document.getElementById('draft').selectionEnd,scroll:[scrollX,scrollY]});});
 for(const f of ['i18n/resources.js','i18n/plateau-resources.js','i18n/toast-resources.js','i18n/action-feedback-resources.js'])await page.addScriptTag({content:read(f)});
 if(compat){
  if(process.env.TOAST_BODY_COMPAT_FILE)await page.addScriptTag({content:fs.readFileSync(process.env.TOAST_BODY_COMPAT_FILE,'utf8')});
  else await page.evaluate(french=>{const langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'],hash=fr=>{let h=0x811c9dc5;for(let i=0;i<fr.length;i++){h^=fr.charCodeAt(i);h=Math.imul(h,0x01000193)>>>0;}return 'toastBodies.b'+h.toString(16).padStart(8,'0');},keys=new Map(french.map(fr=>[fr,hash(fr)]));for(const lang of langs){const obj=RP_I18N_RESOURCES[lang].translation.toastBodies={};for(const [fr,key]of keys)obj[key.split('.')[1]]=lang==='fr'?fr:lang+' · '+fr;}window.RPToastBodyI18n={key:fr=>keys.get(fr)||null,label:fr=>keys.has(fr)?i18next.t(keys.get(fr),{defaultValue:fr}):fr};(window.RP_I18N_CHANGE_CALLBACKS=window.RP_I18N_CHANGE_CALLBACKS||[]).push(()=>{const node=document.getElementById('toast-sub'),fr=node.dataset.rpFr;if(fr&&keys.has(fr)&&!node.childElementCount)node.textContent=RPToastBodyI18n.label(fr);});},[...reuse.reusedBodies.map(r=>r.fr),'12 PA requis — il vous en reste 3.']);
 }
 await page.addScriptTag({content:read('i18n/plateau-init.js')});let presentation=selected(read('plateau-core.js'));
 if(compat){const anchor="document.getElementById('toast-sub').textContent = msg;";assert.ok(presentation.includes(anchor));presentation=presentation.replace(anchor,"const sub=document.getElementById('toast-sub');sub.textContent=RPToastBodyI18n.label(msg);sub.dataset.rpFr=typeof msg==='string'?msg:'';");}
 await page.addScriptTag({content:presentation});
 await page.evaluate(()=>{document.getElementById('draft').focus();document.getElementById('draft').setSelectionRange(2,7);});
 for(const example of fixtures){const before=await page.evaluate(async({example,compat,expectedKey})=>{await i18next.changeLanguage(compat?'en':'fr');state.char.country=example.country||'republic';calls.length=0;window.getFondsDisponiblesOrdinaires=()=>{calls.push(['funds']);return example.funds??45.5;};if(example.withoutFundsHelper)delete window.getFondsDisponiblesOrdinaires;window[example.function](...example.args);return {snapshot:snapshot(),body:document.getElementById('toast-sub').textContent,fr:compat?document.getElementById('toast-sub').dataset.rpFr:document.getElementById('toast-sub').textContent,key:document.querySelector('#toast-sub [data-i18n]')?.dataset.i18n,expectedKey};},{example,compat,expectedKey:owned.has(example.key)?'actionFeedback.'+example.key:reuse.reusedBodies.find(r=>r.sourceKey===example.key).key});assert.equal(before.key,before.expectedKey||undefined,example.id);
 const title=rows.find(r=>r.key===example.key).title;
 for(const lang of ['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de']){const got=await page.evaluate(async({lang,title,originalFr})=>{await i18next.changeLanguage(lang);const marked=document.querySelector('#toast-sub [data-i18n]'),sub=marked||document.getElementById('toast-sub'),values=JSON.parse(marked?.dataset.i18nValues||'{}'),heading=document.querySelector('#toast-result [data-i18n]'),toast=document.getElementById('result-toast');return {same:snapshot(),body:sub.textContent,expected:marked&&i18next.exists(marked.dataset.i18n)?i18next.t(marked.dataset.i18n,{values}):originalFr,marked:!!marked,locale:i18next.language,title:heading.textContent,expectedTitle:RPToastI18n.label(title),dir:sub.dir,titleDir:heading.dir,overflow:document.documentElement.scrollWidth>innerWidth,inside:sub.parentElement.scrollWidth<=sub.parentElement.clientWidth+1,titleInside:heading.parentElement.scrollWidth<=heading.parentElement.clientWidth+1,toastInside:toast.getBoundingClientRect().left>=0&&toast.getBoundingClientRect().right<=innerWidth,images:document.querySelectorAll('#result-toast img').length};},{lang,title,originalFr:before.fr});assert.equal(got.same,before.snapshot,example.id+'/'+lang);assert.equal(got.body,got.expected);assert.equal(got.title,got.expectedTitle);assert.equal(got.locale,lang);assert.equal(got.dir,(owned.has(example.key)||compat)&&lang==='ar'?'rtl':'');if(lang==='fr')assert.equal(got.body,before.fr);assert.equal(got.titleDir,lang==='ar'?'rtl':'');assert.equal(got.overflow,false,example.id+'/'+lang+'/'+width);assert.equal(got.inside,true,example.id+'/'+lang+'/'+width);assert.equal(got.titleInside,true,example.id+'/'+lang+'/'+width);assert.equal(got.toastInside,true,example.id+'/'+lang+'/'+width);assert.equal(got.images,0);}
 }
 if(compat){const guarded=await page.evaluate(async fr=>{await i18next.changeLanguage('en');showToast('Action impossible',fr,false);const node=document.getElementById('toast-sub'),original=node.textContent;const wrongKey=RPI18nPlateau.markToast('actionFeedback.postNamed',fr,{post:'autre'},'Action impossible');node.dataset.rpFr='autre';const staleSource=RPI18nPlateau.markToast(null,fr,undefined,'Action impossible');node.dataset.rpFr=fr;node.textContent='message remplacé';const staleText=RPI18nPlateau.markToast(null,fr,undefined,'Action impossible');node.textContent=original;const titleOnly=RPI18nPlateau.markToast(null,fr,undefined,'Action impossible');return {wrongKey,staleSource,staleText,titleOnly,bodyUnchanged:node.textContent===original,bodyUnmarked:!node.childElementCount};},reuse.reusedBodies[0].fr);assert.deepEqual(guarded,{wrongKey:false,staleSource:false,staleText:false,titleOnly:true,bodyUnchanged:true,bodyUnmarked:true});}
 // A repeated refusal keeps the same action state; changing language does not replay it.
 await page.evaluate(async()=>{await i18next.changeLanguage('fr');for(let i=0;i<3;i++)signalerRefusPa(12);window.repeat=snapshot();});await page.evaluate(()=>i18next.changeLanguage('ar'));assert.equal(await page.evaluate(()=>snapshot()===repeat),true);
 // Missing translation retains the exact French explanation, with original amount strings.
 await page.evaluate(async()=>{await i18next.changeLanguage('fr');signalerRefusCout({raison:'fonds_insuffisants',cost:1250,fondsDisponibles:20});const d=i18next.getResourceBundle('de','translation');delete d.actionFeedback.fundsRequired;i18next.removeResourceBundle('de','translation');i18next.addResourceBundle('de','translation',d);await i18next.changeLanguage('de');});assert.equal(await page.locator('#toast-sub').textContent(),'1 250 FR requis — vous disposez de 20 FR.');
 // The next unmarked message removes the previous markers naturally; no free text translation.
 await page.evaluate(()=>showToast('Texte libre','Réponse <à conserver> — 123',false));for(const lang of ['ar','en','fr']){await page.evaluate(lang=>i18next.changeLanguage(lang),lang);assert.equal(await page.locator('#toast-sub').textContent(),'Réponse <à conserver> — 123');assert.equal(await page.locator('#toast-sub [data-i18n]').count(),0);}
 assert.equal(await page.evaluate(()=>calls.some(c=>c[0]!=='funds')),false);assert.deepEqual(errors,[]);await page.close();}}finally{await browser.close();}
});
